lessons.cli:
# OpenSSL 3.5+: list the available KEMs and test a hybrid handshake
openssl list -kem-algorithms
openssl s_client -connect example.com:443 -groups X25519MLKEM768 </dev/null 2>/dev/null | grep -i group

# nginx built against OpenSSL 3.5+: prefer hybrid, keep a classical fallback
ssl_protocols TLSv1.3 TLSv1.2;
ssl_ecdh_curve X25519MLKEM768:X25519:prime256v1;

# strongSwan 6.x swanctl.conf (abridged): X25519 first, then ML-KEM-768 as additional key exchange 1
connections {
  site-b {
    version = 2
    proposals = aes256gcm16-prfsha384-x25519-ke1_mlkem768
    children {
      net {
        esp_proposals = aes256gcm16-x25519-ke1_mlkem768
      }
    }
  }
}

